<script lang="ts">
 import {onMount,onDestroy} from 'svelte';
 import {invoke} from '@tauri-apps/api/core';
 import {Search,Users,Mail,MessageCircle,X,Copy,RefreshCw,Paperclip,ChevronDown,MoreHorizontal,EyeOff,Eye,Building2} from 'lucide-svelte';
 import {describePresence,type Presence} from './presence';
 import {directoryRows,directoryKey,filterPeople,type Coworker} from './people';
 import {mailConversations,type MailMessage,type MailPage} from './mail';
 import type {Conversation} from './types';
 let {isLive,ownId,presencePermitted,onChat,onEmail,onSignIn,connections=[],members={},onOpenChat,onOpenMail,detailsOpen=true,sidebarOpen=true}:{isLive:boolean;ownId:string;presencePermitted:boolean;onChat:(person:Coworker)=>void;onEmail:(address:string)=>void;onSignIn:()=>void;connections?:Conversation[];members?:Record<string,string[]>;onOpenChat:(id:string)=>void;onOpenMail:(message:MailMessage)=>void;detailsOpen?:boolean;sidebarOpen?:boolean}=$props();
 let query=$state(''),rows=$state<Coworker[]>([]),selected=$state<Coworker|null>(null),manager=$state<Coworker|null>(null),busy=$state(false),error=$state(''),profileError=$state(''),profileBusy=$state(false),presences=$state<Record<string,Presence>>({}),now=$state(Date.now()),updated=$state(0),department=$state(''),sort=$state('az'),limit=$state(100),copyNotice=$state(''),cacheNotice=$state('');
 let mail=$state<MailMessage[]>([]),mailBusy=$state(false),mailError=$state(''),mailSearched=$state(false);
 let hidden=$state<string[]>([]),showHidden=$state(false),menu=$state<string|null>(null);
 const hiddenKey=()=>`taut.people.hidden.v1.${ownId.toLowerCase()}`;
 function toggleHidden(id:string){hidden=hidden.includes(id)?hidden.filter(value=>value!==id):[...hidden,id];menu=null;if(!hidden.length)showHidden=false;try{localStorage.setItem(hiddenKey(),JSON.stringify(hidden));}catch{cacheNotice='Hidden people will only be remembered for this session.';}if(selected?.id===id&&!showHidden){selected=null;manager=null;profileStack=[];++profileSerial;profileBusy=false;mailBusy=false;mail=[];}}
 const visibleRows=$derived(rows.filter(p=>showHidden?hidden.includes(p.id):!hidden.includes(p.id)));
 let alive=true,serial=0,profileSerial=0,refreshing=false;
 let searchInput=$state<HTMLInputElement>();
 let profileViewport=$state<HTMLElement>();
 type ProfileCard={person:Coworker;manager:Coworker|null;notice:string};
 let profileStack=$state<ProfileCard[]>([]);
 function clearProfileContext(){copyNotice='';mail=[];mailError='';mailSearched=false;mailBusy=false;profileViewport?.scrollTo({top:0});}
 function currentCard():ProfileCard|null{return selected?{person:selected,manager,notice:profileError}:null;}
 function returnToCard(index:number,closeCurrent=false){const card=profileStack[index];if(!card)return;const current=currentCard();++profileSerial;selected=card.person;manager=card.manager;profileError=card.notice;profileBusy=false;profileStack=[...profileStack.filter((_,i)=>i!==index),...(!closeCurrent&&current?[current]:[])];clearProfileContext();void refreshPresence();}
 function openManager(){if(!selected||!manager||profileBusy)return;const previous=profileStack.findIndex(card=>card.person.id===manager?.id);if(previous>=0){returnToCard(previous);return;}if(manager.id===selected.id)return;const current=currentCard();profileStack=[...profileStack,...(current?[current]:[])].slice(-11);void choose(manager,true);}
 const email=(p:Coworker)=>p.mail||p.userPrincipalName||'';
 const status=(p:Coworker)=>describePresence(presences[p.id],now);
 const filtered=$derived(filterPeople(visibleRows,query,department,sort));
 const departments=$derived([...new Set(visibleRows.map(p=>p.department).filter((v):v is string=>!!v))].sort());
 const shared=$derived(selected?connections.filter(chat=>members[chat.id]?.includes(selected!.id)):[]);
 const directChat=$derived(shared.find(chat=>chat.chatType==='oneOnOne'&&!chat.id.startsWith('pending:')));
 const files=$derived(shared.flatMap(chat=>chat.messages.filter(m=>!m.deleted).flatMap(m=>(m.attachments??[]).map(file=>({chat,file})))));
 const mailGroups=$derived(mailConversations(mail));
 function clearSearch(){query='';department='';limit=100;searchInput?.focus();}
 async function copyEmail(){if(!selected)return;const address=email(selected);try{await navigator.clipboard.writeText(address);if(alive&&selected&&email(selected)===address)copyNotice='Email copied';}catch{if(alive)copyNotice='Could not copy email. Select the address to copy it manually.';}}
 async function refreshPresence(){if(!presencePermitted||!rows.length||!isLive)return;const version=serial;const ids=[...new Set([...(selected?[selected.id]:[]),...filtered.slice(0,100).map(p=>p.id)])];try{const r=await invoke<{value:Omit<Presence,'seen'>[]}>('graph_presence',{ids});if(!alive||version!==serial)return;const seen=Date.now();presences={...presences,...Object.fromEntries(r.value.map(p=>[p.id,{...p,seen}]))};now=seen;}catch{/* Existing samples expire naturally. */}}
 async function refresh(){if(refreshing||!isLive)return;refreshing=true;busy=true;error='';const version=++serial;try{let next:string|null=null;let fresh:Coworker[]=[];const seen=new Set<string>();do{const page:MailPage<Coworker>=await invoke<MailPage<Coworker>>('people_page',{next});if(!alive||version!==serial)return;if(!Array.isArray(page.value)||fresh.length+page.value.length>10000)throw new Error('Directory response exceeds the local cache limit. Cached people remain available.');fresh=directoryRows([...fresh,...page.value]);next=page.next;if(next){if(seen.has(next)||seen.size>=99||fresh.length>=10000)throw new Error('Directory is too large to refresh completely. Cached people remain available.');seen.add(next);}}while(next);rows=[...new Map(fresh.map(p=>[p.id,p])).values()];updated=Date.now();try{localStorage.setItem(directoryKey(ownId),JSON.stringify({rows,updated}));cacheNotice='';}catch{cacheNotice='Directory is available for this session; local caching is unavailable.';}void refreshPresence();}catch(e){if(alive&&version===serial)error=String(e);}finally{refreshing=false;if(alive&&version===serial)busy=false;}}
 async function choose(person:Coworker,preserveStack=false){if(!preserveStack)profileStack=[];clearProfileContext();selected=person;manager=null;copyNotice='';profileError='';profileBusy=true;mail=[];mailError='';mailSearched=false;mailBusy=false;const version=++profileSerial;void refreshPresence();try{const r=await invoke<{user:Coworker;manager:Coworker|null;notice:string}>('people_profile',{id:person.id});if(!alive||version!==profileSerial)return;selected=directoryRows([r.user])[0]??person;manager=directoryRows(r.manager?[r.manager]:[])[0]??null;profileError=r.notice;}catch(e){if(alive&&version===profileSerial)profileError=String(e);}finally{if(alive&&version===profileSerial)profileBusy=false;}}
 async function findMail(){if(!selected||mailBusy)return;const address=email(selected);if(!/^[^\s"<>:]+@[^\s"<>:]+$/.test(address)){mailError='A valid email address is needed to search connections.';return;}const version=profileSerial;mailBusy=true;mailError='';try{if(!await invoke<boolean>('mail_permission'))throw new Error('Mail.Read consent and a fresh sign-in are needed.');const r=await invoke<MailPage<MailMessage>>('mail_page',{query:{collection:'messages',search:`from:${address} OR to:${address}`}});if(alive&&version===profileSerial){mail=r.value;mailSearched=true;}}catch(e){if(alive&&version===profileSerial)mailError=String(e);}finally{if(alive&&version===profileSerial)mailBusy=false;}}
 onMount(()=>{if(!isLive)return;try{const saved=JSON.parse(localStorage.getItem(hiddenKey())??'[]');if(Array.isArray(saved))hidden=saved.filter((id:unknown)=>typeof id==='string');}catch{/* Ignore invalid preferences. */}try{const cached=JSON.parse(localStorage.getItem(directoryKey(ownId))??'null');if(cached){rows=directoryRows(cached.rows);updated=Number(cached.updated)||0;}}catch{cacheNotice='Saved directory could not be read. Refreshing…';}void refresh();});
 const timer=setInterval(()=>{now=Date.now();void refreshPresence();if(!updated||Date.now()-updated>=15*60*1000)void refresh();},30000);
 onDestroy(()=>{alive=false;++serial;++profileSerial;clearInterval(timer);});
</script>
<svelte:window onkeydown={event=>{if(event.key==='Escape')menu=null;}} onclick={event=>{if(event.target instanceof Element&&!event.target.closest('.person-entry'))menu=null;}}/>
<section class="people-workspace" aria-label="People directory">
 <header><span class="eyebrow">YOUR WORKSPACE</span><h1>People</h1><p>Your coworkers. Your shared context.</p></header>
 {#if !isLive}<div class="people-empty"><Users size={40}/><h2>Your coworkers, within reach.</h2><button class="outline-button" onclick={onSignIn}>Sign in to Microsoft 365</button></div>
 {:else}<div class="people-layout" class:hide-details={!detailsOpen} class:hide-directory={!sidebarOpen}>
 {#if sidebarOpen}<section class="people-search" aria-label="Find coworkers"><div class="directory-controls"><form onsubmit={event=>{event.preventDefault();limit=100;void refreshPresence();}}><label for="people-query">Find a coworker</label><div class="search-field"><input bind:this={searchInput} id="people-query" bind:value={query} oninput={()=>limit=100} maxlength="80" placeholder="Name, email, role…" aria-label="Find a coworker"/>{#if query||department}<button type="button" aria-label="Clear coworker search" title="Clear search" onclick={clearSearch}><X size={16}/></button>{/if}<button type="submit" aria-label="Search"><Search size={18}/></button></div></form>
 <div class="directory-tools"><label>Sort<span class="select-shell"><select aria-label="Sort people" bind:value={sort}><option value="az">Name A–Z</option><option value="za">Name Z–A</option><option value="department">Department</option></select><ChevronDown size={15}/></span></label><label>Department<span class="select-shell"><select aria-label="Department" bind:value={department}><option value="">All departments</option>{#each departments as d}<option value={d}>{d} ({visibleRows.filter(p=>p.department===d).length})</option>{/each}</select><ChevronDown size={15}/></span></label></div>
 {#if hidden.length}<button class="hidden-toggle" aria-pressed={showHidden} onclick={()=>{showHidden=!showHidden;department='';menu=null;}}><EyeOff size={14}/>{showHidden?'Back to directory':`Hidden people (${hidden.length})`}</button>{/if}
 <div class="directory-status"><small>{filtered.length} {filtered.length===1?'person':'people'}{updated?` · Updated ${new Date(updated).toLocaleTimeString()}`:''}</small><button class="outline-button" disabled={busy} aria-label="Refresh directory" onclick={refresh}><RefreshCw size={16}/></button></div>
 {#if busy}<p>Refreshing directory…</p>{/if}{#if error}<p role="alert">{error}</p>{/if}{#if cacheNotice}<p>{cacheNotice}</p>{/if}
 </div><div class="people-list" aria-label="Coworker results">
 {#if !busy&&!filtered.length}<p role="status">{rows.length?'No coworkers found. Try a different name or filter.':'No coworkers loaded.'}</p>{/if}
 {#each filtered.slice(0,limit) as person(person.id)}<div class="person-entry" oncontextmenu={event=>{event.preventDefault();menu=person.id;}} role="group" aria-label={person.displayName}><button class="person-row" class:chosen={selected?.id===person.id} aria-pressed={selected?.id===person.id} onclick={()=>choose(person)}><span class="person-avatar">{person.displayName?.[0]||'?'}</span><span><strong>{person.displayName}</strong><small>{person.jobTitle||email(person)||'Email unavailable'}</small><small style:color={status(person).color}>{status(person).label}</small></span></button><button class="person-more" aria-label="Coworker options" aria-expanded={menu===person.id} onclick={()=>menu=menu===person.id?null:person.id}><MoreHorizontal size={17}/></button>{#if menu===person.id}<div class="person-menu"><button onclick={()=>toggleHidden(person.id)}>{#if hidden.includes(person.id)}<Eye size={16}/>Show this user{:else}<EyeOff size={16}/>Hide this user{/if}</button><small>Only in your TAUT directory</small><button class="menu-close" onclick={()=>menu=null}>Cancel</button></div>{/if}</div>{/each}
 {#if filtered.length>limit}<button class="outline-button" onclick={()=>{limit+=100;void refreshPresence();}}>Show more people</button>{/if}</div></section>{/if}
 <section bind:this={profileViewport} class="person-profile" aria-label="Coworker profile">{#if selected}<div class="profile-deck"><div class="deck-switcher">{#if profileStack.length}<nav class="profile-trail" aria-label="Manager profile history">{#each profileStack as card,index(card.person.id)}<button  onclick={()=>returnToCard(index)} aria-label={`Return to ${card.person.displayName}`}><span class="person-avatar">{card.person.displayName[0]}</span><span>{card.person.displayName}</span><span class="trail-return">↩</span></button>{/each}</nav>{/if}</div><div class="deck-stage">{#each profileStack.slice(-4) as card,index(card.person.id)}<div class="card-backing" style:transform={`translate(${-12*(Math.min(profileStack.length,4)-index)}px, ${-12*(Math.min(profileStack.length,4)-index)}px)`}></div>{/each}{#key selected.id}<div class="profile-card" class:stacked={profileStack.length>0}><div class="profile-cover"><span class="eyebrow">COWORKER PROFILE</span><div class="cover-orbit"></div>{#if profileStack.length}<button class="close-profile" aria-label="Close manager profile" title="Return to previous profile" onclick={()=>returnToCard(profileStack.length-1,true)}><X size={18}/></button>{/if}</div><div class="profile-identity"><span class="person-avatar large">{selected.displayName.split(' ').map(n=>n[0]).slice(0,2).join('')}</span><span class="presence-pill" style:color={status(selected).color}><span>●</span>{status(selected).label}</span><h2>{selected.displayName}</h2><p class="profile-role">{selected.jobTitle||'Your coworker'}</p>{#if selected.department||selected.companyName}<p class="profile-affiliation">{[selected.department,selected.companyName].filter(Boolean).join(' · ')}</p>{/if}<div class="person-actions"><button class="profile-chat" aria-label="Chat" disabled={selected.id===ownId} onclick={()=>selected&&onChat(selected)}><MessageCircle size={18}/>{directChat?'Continue chat':'Start a chat'}</button><button class="outline-button" aria-label="Email" disabled={!email(selected)} onclick={()=>selected&&onEmail(email(selected))}><Mail size={18}/>Write an email</button></div><small>Opening a chat or email does not send anything.</small></div>
 {#if profileBusy}<p class="profile-notice">Refreshing profile…</p>{/if}{#if profileError}<p class="profile-notice" role="alert">{profileError}</p>{/if}
 <div class="profile-sections"><section class="profile-section"><h3><Mail size={16}/>GET IN TOUCH</h3><dl><dt>Email address</dt><dd class="email-value"><span>{email(selected)||'Not available'}</span>{#if email(selected)}<button class="outline-button" aria-label="Copy email address" title="Copy email address" onclick={copyEmail}><Copy size={16}/></button>{/if}</dd>{#if copyNotice}<dd role="status" class="copy-notice">{copyNotice}</dd>{/if}
 {#each [['Work phone',selected.businessPhones?.join(' · ')],['Mobile',selected.mobilePhone]] as [label,value]}{#if value}<dt>{label}</dt><dd>{value}</dd>{/if}{/each}</dl></section>
 <section class="profile-section"><h3><Building2 size={16}/>AT WORK</h3><dl>{#each [['Company',selected.companyName],['Department',selected.department],['Office',selected.officeLocation]] as [label,value]}{#if value}<dt>{label}</dt><dd>{value}</dd>{/if}{/each}</dl>{#if manager}<div class="manager-card"><span class="eyebrow">Manager</span><button class="text-action" onclick={openManager}><span class="person-avatar">{manager.displayName[0]}</span><span><strong>{manager.displayName}</strong><small>{manager.jobTitle??'View profile'}</small></span><span>↗</span></button></div>{/if}</section></div><footer class="profile-footer"><span>Details from your organization</span><button disabled={profileBusy} onclick={()=>selected&&choose(selected,true)}><RefreshCw size={14}/>Refresh profile</button></footer></div>{/key}</div></div>
 {:else}<Users size={42}/><h2>Make the connection.</h2><p>Select a coworker to see their details and shared context.</p>{/if}</section>
 {#if detailsOpen}<aside class="connections" aria-label="Shared connections"><span class="eyebrow">SHARED CONNECTIONS</span>{#if selected}<h2>You + {selected.displayName}</h2><h3>Chats · {shared.length}</h3><small>Known conversations with this coworker. Message history may be incomplete.</small>{#each shared as chat}<button class="connection" onclick={()=>onOpenChat(chat.id)}><MessageCircle size={16}/><span>{chat.name}<small>{chat.preview}</small></span></button>{/each}{#if !shared.length}<p>No shared chats in the loaded conversation list.</p>{/if}
 <h3>Mail</h3><button class="outline-button" disabled={mailBusy||!email(selected)} onclick={findMail}>{mailBusy?'Finding mail…':'Find shared emails'}</button><small>Mailbox search on request · up to 25 messages per search.</small>{#if mailError}<p role="alert">{mailError}</p>{/if}{#each mailGroups as group}<button class="connection" onclick={()=>onOpenMail(group.latest)}><Mail size={16}/><span>{group.latest.subject||'(No subject)'}<small>{group.count} loaded · {group.latest.hasAttachments?'Contains attachments':''}</small></span></button>{/each}{#if mailSearched&&!mail.length}<p>No matching mail found.</p>{/if}
 <h3>Shared files · {files.length}</h3><small>Attachments from loaded shared chat history. Open the source conversation to view or save.</small>{#each files as item}<button class="connection" onclick={()=>onOpenChat(item.chat.id)}><Paperclip size={16}/><span>{item.file.name}<small>{item.chat.name}</small></span></button>{/each}
 {:else}<p>Select a coworker to explore your shared conversations.</p>{/if}</aside>{/if}</div>{/if}
</section>
<style>
.people-workspace{flex:1;min-height:0;overflow:auto;background:var(--surface-base);color:var(--text-primary)}header{padding:28px 36px;border-bottom:1px solid var(--border);background:var(--surface-panel)}h1{font-size:28px;margin:12px 0}p,small,dt{color:var(--text-secondary);line-height:1.6}.people-layout{display:grid;grid-template-columns:minmax(280px,440px) minmax(280px,1fr);min-height:65vh}.people-search{padding:28px;border-right:1px solid var(--border)}label{display:block;font-weight:600;margin-bottom:12px}.search-field{display:flex;align-items:center;gap:10px;border:1px solid var(--border-strong);border-radius:10px;padding:10px;background:var(--surface-raised)}input{min-width:0;flex:1;background:transparent;border:0;color:inherit}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}.search-field button{color:var(--accent);padding:6px}.search-field:focus-within{outline:2px solid var(--accent)}.person-row{display:flex;gap:14px;align-items:center;width:100%;text-align:left;padding:16px;border:1px solid transparent;border-radius:10px;margin:5px 0}.person-row:hover{background:var(--surface-hover)}.person-row.chosen{background:var(--accent-soft);border-color:var(--accent-border)}.person-row small{display:block;overflow-wrap:anywhere}.person-avatar{display:grid;place-items:center;background:var(--accent-soft);color:var(--accent);border-radius:50%;height:44px;width:44px;flex:none;font-weight:700}.large{height:90px;width:90px;font-size:30px;margin:auto}.person-profile{padding:48px clamp(24px,5vw,80px);text-align:center}.person-profile :global(svg){color:var(--accent)}dl{text-align:left;margin:32px auto;max-width:450px}dd{margin:8px 0 22px;overflow-wrap:anywhere}.person-actions{display:flex;justify-content:center;gap:12px;margin:24px}.person-actions button{display:flex;align-items:center;gap:8px}.email-value{display:flex;align-items:center;gap:12px}.email-value button{flex:none;padding:8px}.copy-notice{font-size:12px;margin-top:-12px;color:var(--text-secondary)}.people-empty{text-align:center;padding:70px}@media(max-width:750px){.people-layout{grid-template-columns:1fr}.people-search{border-right:0;border-bottom:1px solid var(--border)}}

.people-layout{grid-template-columns:320px minmax(280px,1fr) 340px;min-height:0;flex:1;overflow:hidden}.people-workspace{display:flex;flex-direction:column;overflow:hidden}.people-search,.person-profile,.connections{overflow:auto;min-height:0}.people-layout.hide-details{grid-template-columns:320px minmax(280px,1fr)}.people-layout.hide-directory{grid-template-columns:minmax(280px,1fr) 340px}.people-layout.hide-details.hide-directory{grid-template-columns:1fr}.connections{border-left:1px solid var(--border);background:var(--surface-panel);padding:28px 22px}.connections h2{font-size:18px;overflow-wrap:anywhere}.connections h3{margin:28px 0 10px;font-size:14px}.connections>small{display:block;margin:10px 0;font-size:12px}.connection{display:flex;gap:10px;width:100%;text-align:left;padding:14px 0;border-bottom:1px solid var(--border);overflow-wrap:anywhere}.connection :global(svg){flex:none;color:var(--accent)}.connection small{display:block;font-size:12px}.directory-tools{display:flex;gap:10px;margin:18px 0}.directory-tools label{font-size:12px;min-width:0;flex:1}.directory-tools select{display:block;width:100%;margin-top:6px;padding:8px;color:var(--text-primary);background:var(--surface-raised);border:1px solid var(--border);border-radius:7px}.directory-status{display:flex;align-items:center;gap:8px;justify-content:space-between}.directory-status button{padding:7px}.person-profile{padding:36px 28px}.people-search{padding:24px 18px}.person-row{padding:12px 8px}.person-row>span:last-child{min-width:0}.person-row small{font-size:12px}@media(max-width:1100px){.people-layout{grid-template-columns:260px minmax(250px,1fr)}.connections{grid-column:2}.people-layout.hide-directory{grid-template-columns:1fr}.hide-directory .connections{grid-column:1}.people-layout{overflow:auto}.people-search{grid-row:1 / 3}.person-profile,.connections{overflow:visible}}@media(max-width:700px){.people-layout,.people-layout.hide-details{display:block;overflow:auto}.people-search,.person-profile,.c